parameters.jsCode:
// Prepare geo-radius targeting, emergency copy, and ad payloads for all 3 channels
const item = $input.first().json.body || $input.first().json;

const county = item.county || 'Georgia';
const lat = item.latitude || 33.7490;
const lng = item.longitude || -84.3880;
const incidentId = item.incident_id || ('GA-' + Date.now());

const headlines = [
  `Injured in ${county} Crash? Get Legal Help Now`,
  `Recent Accident in ${county} County? Know Your Rights`,
  `Georgia Accident Attorneys - 24/7 Rapid Response`
];

const adCopy = `Urgent support for victims of the recent accident near ${county}. Free case review, no fees unless you win. Immediate dispatch available.`;

return [{
  json: {
    incident_id: incidentId,
    county: county,
    latitude: lat,
    longitude: lng,
    radius_miles: 15,
    campaign_name: `Rapid_Crash_Response_${county}_${incidentId}`,
    headline: headlines[0],
    body_copy: adCopy,
    call_to_action: 'CALL_NOW',
    phone_number: '+1-800-555-CRASH',
    landing_page: `https://yourlawfirm.com/georgia-accidents?incident=${incidentId}`,
    budget_usd: 50.00
  }
}];

